### 1) `lic.py`

Key 结构(魔改点:40 字符 × 5bit 打包成 25 字节,非线性流式 tag,混淆常量表):

```
字符:  8   8   8   8   8   8   8   8  → 40 chars, 5bit/char(MSB first) = 200 bit = 25 byte
字节:  [ header 16B ][ tag 9B ]
header: magic LE32 | lic_id LE32 | expiry LE32 | build LE16 | caps LE16
tag   : mix64 链式流 9 轮,每字节 (stream & 0xFF) ^ TAG_SALT[i]
alphabet: Crockford 变体(去 I L O U),共 32 符号
```

```python
"""lic.py — 自定义(魔改)激活码算法。keygen 与客户端校验共用此定义。"""
import struct, time

MAGIC       = 0x4B4C2A5A          # 字节序 LE → "Z*LK"
HEADER_LEN  = 16
TAG_LEN     = 9
NCHARS      = 40
ALPHA       = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
ALPHA_IDX   = {c: i for i, c in enumerate(ALPHA)}
M64         = (1 << 64) - 1

# ---- 客户端内嵌秘密常量(生成混淆表时使用) ----
SEED_A   = 0x9E3779B97F4A7C15
SEED_B   = 0xD1B54A32D192ED03
RC       = (0x243F6A8885A308D3, 0x13198A2E03707344,
            0xA4093822299F31D0, 0x082EFA98EC4E6C89,
            0x452821E638D01377)
TAG_SALT = bytes.fromhex("3f1d9c47a05be2168ec4")   # 9B

CAPS = {"export": 1, "net": 4, "multi": 2, "pro": 8}

def mix64(x):
    x &= M64
    x ^= x >> 33; x = (x * 0xff51afd7ed558ccd) & M64
    x ^= x >> 33; x = (x * 0xc4ceb9fe1a85ec53) & M64
    x ^= x >> 33
    return x & M64

def compute_tag(hdr: bytes) -> bytes:
    assert len(hdr) == HEADER_LEN
    s = mix64(int.from_bytes(hdr, "little") ^ SEED_A)
    s = mix64((s + SEED_B) & M64)
    out = bytearray(TAG_LEN)
    for i in range(TAG_LEN):
        s = mix64((s + RC[i % 5] + ((i * 0x9E3779B97F4A7C15) & M64)) & M64)
        out[i] = (s & 0xFF) ^ TAG_SALT[i]
    return bytes(out)

def pack_hdr(lic_id, expiry, build, caps) -> bytes:
    return struct.pack("<IIIHH", MAGIC & M64, lic_id & 0xFFFFFFFF,
                       expiry & 0xFFFFFFFF, build & 0xFFFF, caps & 0xFFFF)

def bytes_to_chars(b: bytes) -> str:
    total = len(b) * 8
    v = int.from_bytes(b, "big")
    return "".join(ALPHA[(v >> (total - 5 * (i + 1))) & 31] for i in range(total // 5))

def chars_to_bytes(s: str) -> bytes:
    s = s.replace("-", "").replace(" ", "").strip().upper()
    bits = 0
    for ch in s:
        if ch not in ALPHA_IDX:
            raise KeyError(ch)
        bits = (bits << 5) | ALPHA_IDX[ch]
    return bits.to_bytes(len(s) * 5 // 8, "big")

def fmt(raw: str, group: int = 8) -> str:
    return "-".join(raw[i:i + group] for i in range(0, len(raw), group))

def make_key(lic_id=1, expiry=0, build=0x0101, caps=0x000F) -> str:
    """expiry=0 → 永久。expiry 为 unix 秒。"""
    hdr = pack_hdr(lic_id, expiry, build, caps)
    return fmt(bytes_to_chars(hdr + compute_tag(hdr)))

def verify(key: str, now=None):
    """返回 (ok, info_or_reason)。"""
    try:
        raw = chars_to_bytes(key)
    except (KeyError, ValueError):
        return False, "bad-alphabet"
    if len(raw) != HEADER_LEN + TAG_LEN:
        return False, "bad-length"
    hdr, tag = raw[:HEADER_LEN], raw[HEADER_LEN:]
    magic, lic_id, expiry, build, caps = struct.unpack("<IIIHH", hdr)
    if magic != MAGIC:
        return False, "bad-magic"
    if tag != compute_tag(hdr):
        return False, "bad-tag"
    if expiry and expiry < int(now if now is not None else time.time()):
        return False, "expired"
    return True, {"lic_id": lic_id, "expiry": expiry, "build": build,
                  "caps": caps, "perpetual": expiry == 0}
```

### 2) `keygen.py`

```python
#!/usr/bin/env python3
"""keygen.py — 注册机。用法见 --help。"""
import argparse, sys, time, lic

def capbits(names):
    v = 0
    for n in names:
        if n not in lic.CAPS:
            sys.exit("unknown cap: %s (have %s)" % (n, ",".join(lic.CAPS)))
        v |= lic.CAPS[n]
    return v

p = argparse.ArgumentParser(description="activation key generator")
p.add_argument("--id", type=lambda x: int(x, 0), default=1)
g = p.add_mutually_exclusive_group()
g.add_argument("--expiry", type=int, default=0, help="unix 秒,0=永久")
g.add_argument("--days", type=int, help="相对今天 N 天")
p.add_argument("--build", type=lambda x: int(x, 0), default=0x0101)
p.add_argument("--caps", default="pro,net", help="逗号分隔:" + ",".join(lic.CAPS))
p.add_argument("--count", type=int, default=1)
p.add_argument("--from-id", action="store_true", help="连号批量,--id 为起始")
p.add_argument("--out", help="写入文件")
a = p.parse_args()

exp = a.expiry
if a.days:
    exp = int(time.time()) + a.days * 86400
caps = capbits([c for c in a.caps.split(",") if c])

lines = []
for k in range(a.count):
    lid = a.id + k if a.from_id else a.id
    key = lic.make_key(lid, exp, a.build, caps)
    ok, info = lic.verify(key)
    assert ok, info
    lines.append("%s\tid=%d exp=%d build=0x%04x caps=0x%04x%s" %
                 (key, lid, exp, a.build, caps, " (perpetual)" if exp == 0 else ""))
txt = "\n".join(lines)
if a.out:
    open(a.out, "w").write(txt + "\n")
else:
    print(txt)
```

### 3) `gen_secret_table.py`(产出客户端混淆常量)

```python
#!/usr/bin/env python3
"""把 lic.py 的明文常量编码成客户端可内嵌的混淆表 lic_secrets.h。"""
import lic, struct, sys

BLOB_LEN = 72
OBF_KEY  = bytes.fromhex("b7d1e35a4c980f62")

def hx(b): return ", ".join("0x%02x" % x for x in b)

def main():
    plain = bytearray()
    plain += lic.SEED_A.to_bytes(8, "little")
    plain += lic.SEED_B.to_bytes(8, "little")
    for c in lic.RC:
        plain += c.to_bytes(8, "little")
    plain += lic.TAG_SALT
    plain += bytes(BLOB_LEN - len(plain))
    assert len(plain) == BLOB_LEN
    blob = bytes(p ^ OBF_KEY[i & 7] for i, p in enumerate(plain))

    hdr = lic.pack_hdr(0x00010203, 0x05F5E100, 0x0203, 0x000F)   # 自检向量
    tag = lic.compute_tag(hdr)

    a2v = ["."] * 128
    for c, i in lic.ALPHA_IDX.items():
        a2v[ord(c)] = str(i)

    out = f"""/* AUTO-GENERATED by gen_secret_table.py — do not hand-edit */
#ifndef LIC_SECRETS_H
#define LIC_SECRETS_H
#define LIC_BLOB_LEN {BLOB_LEN}
static const unsigned char OBF_KEY[8]   = {{ {hx(OBF_KEY)} }};
static const unsigned char OBF_BLOB[{BLOB_LEN}] = {{ {hx(blob)} }};
static const unsigned char SELFTEST_HDR[16] = {{ {hx(hdr)} }};
static const unsigned char SELFTAG[9]    = {{ {hx(tag)} }};
static const char LIC_A2V[129] = "{''.join(a2v)}";
#endif
"""
    open(sys.argv[1] if len(sys.argv) > 1 else "lic_secrets.h", "w").write(out)
    print("wrote lic_secrets.h  blob=%dB selftag=%s" % (BLOB_LEN, tag.hex()))

if __name__ == "__main__":
    main()
```

