    """regions: [(start_off, end_off, name)] -> [(file_off, matched_bytes)]"""
    hits, n, m = [], len(buf), len(pattern)
    if m == 0:
        return hits
    first = pattern[0]
    for i in range(0, n - m + 1):
        if first in WILDCARD or buf[i] == first:
            if all(b in WILDCARD or buf[i + j] == b for j, b in enumerate(pattern)):
