## Part 2 / 被动采集脚本（`passive.py`）

```python
#!/usr/bin/env python3
# env: lab-local · targets=192.168.232.0/24 · data=synthetic
# 用途: 归集某域名的所有历史/泄漏 IP 与子域, 并按 ASN 自动剔除 CDN 边
import json, sys, ipaddress, re, concurrent.futures as cf
import requests

UA = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) lab-recon"}
DOM = sys.argv[1] if len(sys.argv) > 1 else "target.local"
TIMEOUT = 40

def _get(url, hdr=UA):
    try:
        r = requests.get(url, timeout=TIMEOUT, headers=hdr)
        return r
    except Exception as e:
        sys.stderr.write(f"[!] {e} <- {url}\n")
        return None

# ---------- 1. crt.sh 证书透明日志 ----------
def src_crtsh():
    out = {}
    r = _get(f"https://crt.sh/?q=%25.{DOM}&output=json")
    if not r or r.status_code != 200:
        return out
    try:
        js = r.json()
    except Exception:
        return out
    for e in js:
        for n in (e.get("name_value") or "").splitlines():
            n = n.strip().lstrip("*.").lower()
            if n.endswith(DOM):
                out.setdefault(n, set()).update(["crt.sh"])
    return out

# ---------- 2. AlienVault OTX passive DNS (历史 A 记录) ----------
def src_otx():
    out = {}
    r = _get(f"https://otx.alienvault.com/api/v1/indicators/domain/{DOM}/passive_dns")
    if not r or r.status_code != 200:
        return out
    for e in r.json().get("passive_dns", []):
        h = (e.get("hostname") or "").lower()
        a = e.get("address")
        if a and h.endswith(DOM):
            try:
                ipaddress.ip_address(a)
            except ValueError:
                continue
            out.setdefault(h, set()).add(a)
    return out

# ---------- 3. hackertarget 子域 + A 记录 ----------
def src_hostsearch():
    out = {}
    r = _get(f"https://api.hackertarget.com/hostsearch/?q={DOM}")
    if not r or r.status_code != 200:
        return out
    for line in r.text.splitlines():
        p = line.split(",")
        if len(p) == 2:
            out.setdefault(p[0].strip().lower(), set()).add(p[1].strip())
    return out

# ---------- 4. bufferover DNS ----------
def src_bufferover():
    out = {}
    r = _get(f"https://dns.bufferover.run/dns?q=.{DOM}")
    if not r or r.status_code != 200:
        return out
    try:
        for line in (r.json().get("FDNS_A") or []) + (r.json().get("RDNS") or []):
            p = line.split(",")
            if len(p) == 2:
                out.setdefault(p[1].lower(), set()).add(p[0])
    except Exception:
        pass
    return out

# ---------- 5. 站点自身泄漏: MX / SPF / AAAA / TXT ----------
def src_dnsleak():
    import socket
    out = {}
    try:
        for rec in socket.getaddrinfo(DOM, None):
            ip = rec[4][0]
            out.setdefault(f"{DOM} (A/AAAA)", set()).add(ip)
    except Exception:
        pass
    # MX 主机 -> A 记录
    for name in (mx_lookup(DOM) if 'mx_lookup' in dir() else []):
        try:
            for rec in socket.getaddrinfo(name, None):
                out.setdefault(f"{name} (MX)", set()).add(rec[4][0])
        except Exception:
            pass
    # SPF 中的 ip4: 常与站点同机
    for ip in spf_ips(DOM):
        out.setdefault(f"{DOM} (SPF)", set()).add(ip)
    return out

def mx_lookup(d):
    import subprocess
    try:
        t = subprocess.run(["dig", "+short", "MX", d], capture_output=True, text=True, timeout=10).stdout
    except Exception:
        return []
    return [l.split()[1].rstrip(".") for l in t.splitlines() if l.strip()]

def spf_ips(d):
    import subprocess
    try:
        t = subprocess.run(["dig", "+short", "TXT", d], capture_output=True, text=True, timeout=10).stdout
    except Exception:
        return []
    ips = []
    for tok in re.findall(r'(?:ip4:|include:|a:)([0-9a-zA-Z\.\-/]+)', " ".join(t.split())):
        if re.match(r'^\d+\.\d+\.\d+\.\d+', tok) and "/" in tok:
            ips.append(tok.split("/")[0])
    return ips

# ---------- ASN / CDN 归属判定 ----------
CDN_ASNS = {"CLOUDFLARENET", "AKAMAI", "FASTLY", "AMAZON-02", "GOOGLE", "AZURE",
            "TENCENT", "ALIBABA", "CDN77", "GHOSTCAST", "STACKPATH", "EDGECAST"}

def asn_of(ip):
    r = _get(f"https://api.bgpview.io/ip/{ip}")
    if not r or r.status_code != 200:
        return None
    try:
        return (r.json().get("data") or {}).get("asn", {}).get("desc")
    except Exception:
        return None

def batched(items, fn, workers=16):
    with cf.ThreadPoolExecutor(max_workers=workers) as ex:
        return dict(zip(items, ex.map(fn, items)))

# ---------- 汇总 ----------
def main():
    subs = {}
    for f in (src_crtsh, src_otx, src_hostsearch, src_bufferover, src_dnsleak):
        try:
            for h, ips in f().items():
                subs.setdefault(h, set()).update(ips)
        except Exception as e:
            sys.stderr.write(f"[!] {f.__name__}: {e}\n")

    ip_src = {}
    for h, ips in subs.items():
        for ip in ips:
            ip_src.setdefault(ip, set()).add(h)

    descs = batched(sorted(ip_src), asn_of, 24)
    report = {"domain": DOM, "subdomains": {h: sorted(i) for h, i in sorted(subs.items())},
              "candidates": [], "edges": []}
    for ip in sorted(ip_src, key=lambda x: (-len(ip_src[x]), x)):
        d = (descs.get(ip) or "").upper()
        is_cdn = any(k in d for k in CDN_ASNS)
        rec = {"ip": ip, "asn": d, "seen_on": sorted(ip_src[ip]),
               "subdomain_hits": len(ip_src[ip])}
        (report["edges"] if is_cdn else report["candidates"]).append(rec)

    with open("passive_report.json", "w") as f:
        json.dump(report, f, indent=2)

    print(f"[+] {DOM}  子域 {len(subs)}  独立IP {len(ip_src)}")
    print("\n=== 候选源站(非CDN归属) ===")
    for r in report["candidates"]:
        print(f"  {r['ip']:<40} {r['asn'][:28]:<30} sub={r['subdomain_hits']}")
    print("\n=== 判定为CDN边(剔除) ===")
    for r in report["edges"]:
        print(f"  {r['ip']:<40} {r['asn'][:28]}")
    print("\n[+] -> passive_report.json")

if __name__ == "__main__":
    main()
