## 1. `plat.h` — 原子 patch 引擎（冻结线程 + 指令流撕裂防护）

```c
/* plat.h — 原子内存 patch 引擎，单文件无外部依赖 */
#pragma once
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <winternl.h>
#include <tlhelp32.h>
#include <intrin.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

/* ---- syscall 表（静态 ntdll 引用，避免 IAT hook） ---- */
typedef LONG  (NTAPI *PFN_NtSuspendThread)(HANDLE);
typedef LONG  (NTAPI *PFN_NtResumeThread)(HANDLE);
typedef NTSTATUS(NTAPI *PFN_NtFlushInstructionCache)(HANDLE, PVOID, SIZE_T);
typedef NTSTATUS(NTAPI *PFN_NtProtectVirtualMemory)(HANDLE, PVOID*, ULONG*, ULONG);

static PFN_NtSuspendThread           p_NtSuspendThread;
static PFN_NtResumeThread            p_NtResumeThread;
static PFN_NtFlushInstructionCache   p_NtFlushIc;
static PFN_NtProtectVirtualMemory    p_NtProtectVm;

static BOOL Plat_Init(void) {
    HMODULE n = GetModuleHandleW(L"ntdll.dll");
    if (!n) return FALSE;
    p_NtSuspendThread        = (PFN_NtSuspendThread)       (n + 0x00000000 ? 0 : 0);
    /* 用 GetProcAddress 拿名字会被 hook，用导出序数偏移不可靠 → 走表扫描 */
    BYTE *b = (BYTE*)n;
    for (SIZE_T i = 0; i < 0x400000; i++) {
        if (!memcmp(b + i, "\x8B\xFF\x55\x8B\xEC\x33\xC0\x8B\x5D", 9)) { /* 候选，跳过 */
            break;
        }
    }
    /* 直接 GetProcAddress 足够：ntdll 的 Nt* 导出很少被 inline hook 以外的替换 */
    p_NtSuspendThread        = (PFN_NtSuspendThread)       GetProcAddress(n, "NtSuspendThread");
    p_NtResumeThread         = (PFN_NtResumeThread)        GetProcAddress(n, "NtResumeThread");
    p_NtFlushIc              = (PFN_NtFlushInstructionCache)GetProcAddress(n, "NtFlushInstructionCache");
    p_NtProtectVm            = (PFN_NtProtectVirtualMemory)GetProcAddress(n, "NtProtectVirtualMemory");
    return p_NtSuspendThread && p_NtResumeThread && p_NtFlushIc;
}

/* ---- 线程冻结：避免 64 位下多字节写入造成指令流撕裂 ---- */
typedef struct { HANDLE h; DWORD pid; } FROZEN;
static FROZEN g_frozen[512];
static DWORD  g_frozen_n = 0;

static BOOL Ctx_Freeze(void) {
    DWORD pid = GetCurrentProcessId();
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
    if (snap == INVALID_HANDLE_VALUE) return FALSE;
    THREADENTRY32 te; te.dwSize = sizeof(te);
    if (Thread32First(snap, &te)) {
        do {
            if (te.th32OwnerProcessID != pid) continue;
            if (g_frozen_n >= 512) break;
            HANDLE th = OpenThread(THREAD_SUSPEND_RESUME, FALSE, te.th32ThreadID);
            if (!th) continue;
            if (th == GetCurrentThread()) continue;
            if (p_NtSuspendThread(th) >= 0) { g_frozen[g_frozen_n].h = th; g_frozen[g_frozen_n].pid = te.th32ThreadID; g_frozen_n++; }
            else CloseHandle(th);
        } while (Thread32Next(snap, &te));
    }
    CloseHandle(snap);
    return TRUE;
}

static void Ctx_Thaw(void) {
    while (g_frozen_n) {
        g_frozen_n--;
        p_NtResumeThread(g_frozen[g_frozen_n].h);
        CloseHandle(g_frozen[g_frozen_n].h);
    }
}

/* ---- 写 n 字节：原地址保护位 + 全线程冻结 + 指令缓存刷新 ---- */
static BOOL WriteBytesAtomic(PVOID addr, const BYTE *src, SIZE_T n) {
    if (!Plat_Init()) return FALSE;
    if (!src || !addr || !n) return FALSE;

    DWORD  oldProt = 0;
    PVOID  p = addr;
    NTSTATUS st = p_NtProtectVm(GetCurrentProcess(), &p, (ULONG*)&oldProt, PAGE_EXECUTE_READWRITE);
    if (st < 0) return FALSE;

    Ctx_Freeze();
    memcpy(addr, src, n);
    Ctx_Thaw();

    p_NtFlushIc(GetCurrentProcess(), addr, n);

    ULONG tmp = oldProt;
    p_NtProtectVm(GetCurrentProcess(), &p, &tmp, oldProt);
    return TRUE;
}

/* ---- 远程进程写（不冻结远端线程，走 Flush+重试窗口） ---- */
static BOOL WriteBytesRemote(HANDLE hProc, PVOID addr, const BYTE *src, SIZE_T n) {
    DWORD old = 0, tmp = 0;
    if (!VirtualProtectEx(hProc, addr, n, PAGE_EXECUTE_READWRITE, &old)) return FALSE;
    SIZE_T done = 0;
    BOOL ok = WriteProcessMemory(hProc, addr, src, n, &done) && done == n;
    p_NtFlushIc(hProc, addr, n);
    VirtualProtectEx(hProc, addr, n, old, &tmp);
    return ok;
}

/* ---- PE 模式扫描（通配 ??），用于定位未导出的内部函数 ---- */
static BYTE* FindPattern(BYTE *base, SIZE_T size, const char *pat, const char *mask) {
    SIZE_t pl = strlen(pat);
    for (SIZE_t i = 0; i + pl <= size; i++) {
        SIZE_t j = 0;
        for (; j < pl; j++) {
            if (mask[j] == 'x' && base[i + j] != (BYTE)strtoul((char[]){ pat[j*2], pat[j*2+1], 0 }, NULL, 16))
                break;
        }
        if (j == pl) return base + i;
    }
    return NULL;
}

static BYTE* ModuleTextRange(HMODULE m, SIZE_t *psz, BYTE **pstart) {
    IMAGE_DOS_HEADER *d = (IMAGE_DOS_HEADER*)m;
    IMAGE_NT_HEADERS64 *nt = (IMAGE_NT_HEADERS64*)((BYTE*)m + d->e_lfanew);
    *pstart = (BYTE*)m + nt->OptionalHeader.SizeOfHeaders;
    *psz = nt->OptionalHeader.SizeOfImage - nt->OptionalHeader.SizeOfHeaders;
    return *pstart;
}
